"""Reproducible scorecards; keep retained R, fresh OHLC and tick evidence separate."""
import csv,gzip,hashlib,json,subprocess
from datetime import datetime
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];OUT=ROOT/'docs/research/personal-edge-20261127'
def load(p):return json.loads(p.read_text())
def write(p,x):p.write_text(json.dumps(x,indent=2,allow_nan=False)+'\n')
def n(x):return '—' if x is None else f'{x:.2f}'
def table(headers,rows):return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(str(v) for v in row)+' |' for row in rows])

def main():
    ledger=load(ROOT/'src/data/saved-ledger-trades.json');old=load(ROOT/'docs/research/edge-evidence-20261127/scorecard.json')
    rows=[]
    for source in old['configurations']:
        row=dict(source);ts=[t for t in ledger['trades'] if t['strategy_id']==row['strategy_id']]
        wins=[t['realized_r'] for t in ts if t['realized_r']>0];losses=[t['realized_r'] for t in ts if t['realized_r']<0]
        days=sum((datetime.fromisoformat(c['end_exclusive'])-datetime.fromisoformat(c['start'])).total_seconds()/86400 for c in row['coverage'])
        row.update(average_win_r=sum(wins)/len(wins) if wins else None,average_loss_r=sum(losses)/len(losses) if losses else None,covered_calendar_days=days,decisions_per_covered_calendar_day=len(ts)/days,active_entry_days=len({t['entry_time'][:10] for t in ts}),individual_order_count=None)
        rows.append(row)
    write(OUT/'existing-16-detailed.json',dict(schema='retained-ledger-detailed/v1',ledger_sha256=hashlib.sha256((ROOT/'src/data/saved-ledger-trades.json').read_bytes()).hexdigest(),costs=ledger['costs'],rows=rows,limitations=['R units, not dollar or percentage account returns. Unequal coverage; portfolio admission and correlation exist.','Covered calendar days include weekends; active entry days are different. Orders/deals are not retained.','Complete-month positive R is not a profitable-month probability or subscription-adjusted return.']))
    cols=['strategy_id','decisions','net_r','win_rate_pct','average_win_r','average_loss_r','profit_factor','expectancy_r','average_holding_minutes','decisions_per_covered_calendar_day','covered_calendar_days']
    with (OUT/'existing-16-detailed.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=cols);w.writeheader();w.writerows({k:r[k] for k in cols} for r in rows)
    monthcols=['strategy_id','month','complete_market_time_coverage','coverage_calendar_days','decisions','net_r','win_rate_pct','profit_factor','expectancy_r']
    with (OUT/'existing-16-months.csv').open('w') as f:
        w=csv.DictWriter(f,fieldnames=monthcols);w.writeheader()
        for r in rows:
            for m in r['months']:w.writerow({k:r['strategy_id'] if k=='strategy_id' else m[k] for k in monthcols})
    receipts=json.loads(gzip.decompress((OUT/'fresh-crypto-receipts.json.gz').read_bytes()))
    terminal=[]
    for r in receipts['results']:
        key=f"{r['lineup']}:{r['capital']}:{r['risk_pct']}:{r['leverage']}:{r['stress']}"
        ts=receipts['decisions'][key];natural=[t for t in ts if t['reason']!='TERMINAL_CLOSE'];forced=[t for t in ts if t['reason']=='TERMINAL_CLOSE']
        terminal.append(dict(case=key,naturally_closed_decisions=len(natural),naturally_closed_net_money=sum(t['net'] for t in natural),terminal_closed_decisions=len(forced),terminal_closed_net_money=sum(t['net'] for t in forced)))
    write(OUT/'fresh-crypto-terminal-audit.json',dict(meaning='Decomposition of costed total decision cash. Includes allocated entry fees/funding. Natural vs terminal close is not a separate investable portfolio.',cases=terminal))
    lines=['# HashiBot Personal strategy evidence — 27 November 2026','','The catalogue remains 16 existing configurations plus five Gold Turbo strategies. The additional compression prototype is outside the catalogue. No paid/live execution or Prop policy was enabled.','','## Existing 16: retained costed trades','','These 1,159 records were reused, not regenerated. Results are net R from unequal historical windows, not fresh account backtests. Orders and deals cannot be reconstructed from these records. Full covered months, gaps, dates and chronological halves are retained in `existing-16-detailed.json`.','',''+table(['Configuration','Decisions','Net R','Win %','Avg win R','Avg loss R','PF','Hold min','Decisions/covered day'],[[r['strategy_id'],r['decisions'],n(r['net_r']),n(r['win_rate_pct']),n(r['average_win_r']),n(r['average_loss_r']),n(r['profit_factor']),n(r['average_holding_minutes']),n(r['decisions_per_covered_calendar_day'])] for r in rows]),'','## Fresh Crypto: 1–26 November, 26 calendar days','','Ten existing launch assets, native 4h/1h/15m/5m candle sources as required, paid funding and current volume filters. Six frozen production entry families, two research combinations and one frozen prototype. Combination admission ranks reward/risk, with deterministic ID ties under shared risk/margin constraints; it does not replay the full production Smart Account Brain. 576 capital/risk/leverage/cost scenarios. Base commissions 5 bps per side, slippage 3 bps per side (ETH complementary 7.5); stress slippage 10 bps (ETH complementary 15). This is an OHLC execution screen, not real bid/ask or exchange qualification. Stops take priority within ambiguous bars. Next-bar entry; gap losses and approximate liquidation checks included.','','The table uses $500, 10× available leverage and 1% fixed decision risk. Leverage changes available margin, not the profit of an unchanged position. Risk headroom reserves the full original decision risk until closure, including after partial exits; this is conservative. Daily/peak limits are experimental 15%/60%, correlated risk 10%, entry margin 50%. These are not customer defaults. Drawdown is sampled equity, not verified intrabar maximum.','',''+table(['Lineup','Return %','Stress %','DD %','Decisions/day','Win %','Avg win $','Avg loss $','Hold min'],[[r['lineup'],n(r['return_pct']),n(next(q['return_pct'] for q in load(OUT/'fresh-crypto-summary.json')['results'] if q['lineup']==r['lineup'] and q['capital']==500 and q['risk_pct']==1 and q['leverage']==10 and q['stress'])),n(r['close_sampled_drawdown_pct']),f"{r['closed_decisions']}/26 = {r['closed_decisions']/26:.2f}",n(r['win_rate_pct']),n(r['average_win_money']),n(r['average_loss_money']),n(r['average_hold_minutes'])] for r in load(OUT/'fresh-crypto-summary.json')['results'] if r['capital']==500 and r['risk_pct']==1 and r['leverage']==10 and not r['stress']]),'','### Crypto combined sizing comparison','','All rows use the same six-family arbitration, prices, costs and 15%/60% limits; sizing changes portfolio admission and realized paths. No risk level was tuned for a guaranteed result.','',''+table(['Capital','Risk %','Leverage','Return %','Stress %','Sampled DD %','Decisions','After $100 fee $'],[[r['capital'],r['risk_pct'],r['leverage'],n(r['return_pct']),n(next(q['return_pct'] for q in load(OUT/'fresh-crypto-summary.json')['results'] if q['lineup']==r['lineup'] and q['capital']==r['capital'] and q['risk_pct']==r['risk_pct'] and q['leverage']==r['leverage'] and q['stress'])),n(r['close_sampled_drawdown_pct']),r['closed_decisions'],n(r['net_after_full_100_subscription'])] for r in load(OUT/'fresh-crypto-summary.json')['results'] if r['lineup']=='ADAPTIVE_EXISTING_SIX' and r['capital'] in (100,500,1000,25000) and not r['stress']]),'','A full $100 subscription is an external cost sensitivity; it was not withdrawn from collateral. Terminal positions are forcibly marked/closed at the period end; open-before-terminal counts and exit reasons are disclosed in the JSON. One partial November cannot establish median monthly returns, profitable-month probability or sustainable growth. The ETH complementary case uses perpetual data, unlike its older spot-reference ledger. The losing compression prototype remains rejected. No existing weak component is qualified merely by belonging to a positive combination. At $500 / 1% / 10×, 24 naturally closed decisions contributed $214.67 and 10 terminal closures contributed $15.79. Average holding time was about 123 hours: this Crypto result is a swing result, not evidence for Gold Turbo scalping. Full terminal decomposition is in `fresh-crypto-terminal-audit.json`.','','## Existing Gold Standard: October ticks, higher Personal sizing','','These three unchanged rules are intraday/swing, not the new Turbo scalpers. Separate accounts at each size; returns must not be added. Actual retained bid/ask ticks, 100 oz/lot, 0.01 minimum/step, 100× leverage, $3.50/lot/side commission. Base slippage $0.02/side and 200 ms execution; stress $0.05 and 500 ms. Same 15% daily/60% peak/50% entry margin experimental constraints across risk levels. Overnight financing is unverified and omitted; profits are before financing and subscription. Full 96 cases and receipts are retained.','',''+table(['Configuration','Capital','Risk %','Return %','Stress %','DD %','Decisions','Avg win $','Avg loss $'],[[r['arm']['strategy_id'],r['arm']['capital'],r['arm']['risk'],n(r['returnPct']),n(next(q['returnPct'] for q in load(OUT/'personal-gold-summary.json')['result']['results'] if q['arm']['strategy_id']==r['arm']['strategy_id'] and q['arm']['capital']==r['arm']['capital'] and q['arm']['risk']==r['arm']['risk'] and q['arm']['stress'])),n(r['drawdownPct']),r['closedTrades'],n(r['average_win_money']),n(r['average_loss_money'])] for r in load(OUT/'personal-gold-summary.json')['result']['results'] if r['arm']['capital'] in (500,25000) and not r['arm']['stress']]),'']
    turbo=[]
    for risk in (1,3,5):
        p=ROOT/f'.tmp/personal-turbo-corrected-{risk}.json'
        if not p.exists():continue
        d=load(p)
        if risk in (1,5):
            original=json.loads(subprocess.check_output(['git','show','8b036a4:docs/research/personal-edge-20261127/turbo-research-protocol.json'],cwd=ROOT,text=True))
            d['finish_time_runtime_hash_not_executed']=d['strategy_file_sha256']['gold_turbo/runtime.py']
            d['strategy_file_sha256']['gold_turbo/runtime.py']=original['research_runtime_sha256']
            d['personal_research_protocol']=original
            d['matching_production_source_commit']='8b036a494181061d9c1d30a8c092e5c4b1e2a870'
            d['provenance_correction']='These running processes imported the pre-handler runtime. Its hash is restored from the committed start protocol; the old replayer read mutable on-disk hashes at finish. Future replays snapshot provenance before execution.'
        for r in d['results']:
            key=f"{r['lineup']}:{r['capital']:g}"
            b=d['closed_baskets'][key]
            # Restore filled-basket counts from exact reservation comment hashes
            # for runs predating explicit filled_orders instrumentation.
            entries=[f for f in d['fills'][key] if f['entry']==0]
            for basket in b:
                if 'filled_orders' not in basket:
                    basket['filled_orders']=sum(f['comment']=='ht:'+hashlib.sha256(f"{basket['basket_id']}:{f['entry_plan']['opportunity_id']}:main".encode()).hexdigest()[:24] for f in entries)
            filled=[v for v in b if v['filled_orders']]
            r['independent_baskets']=len(filled)
            r['baskets_per_selected_session']=len(filled)/22
            r['win_rate_pct']=100*sum(v['net']>0 for v in filled)/len(filled) if filled else None
            r['expectancy_money']=sum(v['net'] for v in filled)/len(filled) if filled else None
            wins=[v['net'] for v in b if v['net']>0];losses=[v['net'] for v in b if v['net']<0]
            if abs(sum(v['net'] for v in b)-r['final_equity']+r['capital'])>1e-5:raise ValueError('TURBO_CASH_AUDIT')
            r.update(risk_pct=risk,average_win_money=sum(wins)/len(wins) if wins else None,average_loss_money=sum(losses)/len(losses) if losses else None)
            turbo.append(r)
        d['summary_postprocessing']='Exact reservation-comment matching counts filled baskets, including breakeven; rejected unfilled reservations are excluded. Raw fills and source/runtime hashes remain unchanged.'
        (OUT/f'turbo-corrected-{risk}-receipts.json.gz').write_bytes(gzip.compress(json.dumps(d,separators=(',',':')).encode(),mtime=0))
    if len(turbo)==72:
        write(OUT/'turbo-corrected-summary.json',dict(schema='turbo-personal-corrected/v1',results=turbo,scope='22 October weekdays, 08–16 UTC only; observed nonempty native quote bars. Selected sessions, not continuous full month.'))
        lines+=['## All five Turbo scalpers: corrected local runtime','','22 October weekdays, 08–16 UTC only; 2,643,309 original quotes. The margin correction includes existing account margin, uncertain pending reservations and margin-constrained volume reduction. All five retain their scalping horizons. Fixed 0.2% basket equity target; 20% session profit lock, 5% session trailing; 15% daily, 60% peak experimental loss allowances; 50% entry margin cap. The target and margin limits mean increasing configured risk need not increase permitted volume or returns. No parameter sweep or entry retuning. These are historical fake-terminal execution replays, not native broker certification.','',''+table(['Lineup','Capital','Risk %','Return %','DD %','Baskets/day','Entry orders','Win %','Avg win $','Avg loss $','Hold min'],[[r['lineup'],r['capital'],r['risk_pct'],n(r['net_return_pct']),n(r['maximum_drawdown_pct']),f"{r['independent_baskets']}/22 = {r['baskets_per_selected_session']:.2f}",r['individual_orders'],n(r['win_rate_pct']),n(r['average_win_money']),n(r['average_loss_money']),n(r['average_holding_minutes'])] for r in turbo if r['capital'] in (500,25000)]),'','The apparent independent unit is a coordinated basket, not each order. No stressed second Turbo replay is claimed here. Quotes outside the selected sessions were not traded. Full reasons, source hashes, fills, realized basket cash and cases are retained in compressed receipts.']
        catalogue=[dict(strategy_id=r['strategy_id'],basis='RETAINED_LEDGER_R_UNITS',decisions=r['decisions'],net_value=r['net_r'],net_unit='R',win_rate_pct=r['win_rate_pct'],average_win=r['average_win_r'],average_loss=r['average_loss_r'],average_win_loss_unit='R',participation=r['decisions_per_covered_calendar_day'],participation_unit='PER_COVERED_CALENDAR_DAY',average_hold_minutes=r['average_holding_minutes'],profitability_validated=False) for r in rows]
        for r in turbo:
            if r['capital']!=500 or r['risk_pct']!=1 or r['lineup']=='adaptive-all-five':continue
            catalogue.append(dict(strategy_id='gold.turbo-'+r['lineup'],basis='OCT_SELECTED_TICK_SESSIONS_500_USD_1PCT',decisions=r['independent_baskets'],net_value=r['net_return_pct'],net_unit='PERCENT',win_rate_pct=r['win_rate_pct'],average_win=r['average_win_money'],average_loss=r['average_loss_money'],average_win_loss_unit='USD_PER_BASKET',participation=r['baskets_per_selected_session'],participation_unit='PER_SELECTED_8H_SESSION',average_hold_minutes=r['average_holding_minutes'],profitability_validated=False))
        if len(catalogue)!=21:raise ValueError('EXPECTED_21_CONFIGURATIONS')
        write(OUT/'catalogue-21.json',dict(meaning='Different evidence units and periods. Do not rank or aggregate net_value across bases.',rows=catalogue))
        with (OUT/'catalogue-21.csv').open('w') as f:
            w=csv.DictWriter(f,fieldnames=list(catalogue[0]));w.writeheader();w.writerows(catalogue)
        lines+=['','At $500 / 1% risk, the shared 0.2% profit target frequently closes small winners while stopped trades lose more. Trend averaged about $0.83 per winning basket versus $3.71 per loser; its 76.9% win rate was insufficient. Higher risk and restored margin-limited participation did not repair the edge. The two-decision positive Momentum arm at 5% is inadequate evidence. These results do not support selling the current Turbo lineup as profitable.','', 'The 1%/5% runs completed without the frozen-envelope reservation exception on the first corrected runtime; the 3% run uses the subsequent safe-rejection handler. Exact runtime hashes are retained per receipt. Entry logic is identical; the handler preserves original limits.']
    else:lines+=['## Gold Turbo corrected replay','','Corrected 72-case replay is still running; no earlier over-margin rejection results are represented as final corrected results.']
    target_cases=[]
    for target in (.2,.4):
        p=ROOT/f'.tmp/turbo-target-{target}.json'
        if not p.exists():continue
        d=load(p)
        for r in d['results']:r['basket_target_pct']=target;target_cases.append(r)
        (OUT/f'turbo-target-{target}-receipts.json.gz').write_bytes(gzip.compress(p.read_bytes(),mtime=0))
    if len(target_cases)==24:
        write(OUT/'turbo-target-comparison.json',dict(protocol=load(OUT/'target-experiment.json'),results=target_cases))
        lines+=['','## One focused profit-capture experiment','','Six known development sessions (23, 26–30 October), reset $500/$25,000 accounts, 1% risk, unchanged entry rules/holding limits and execution assumptions. Compare the original 0.2% basket target against the user-requested 0.4%; no other parameter change. This is not an unseen holdout or a full-month comparison.','',''+table(['Lineup','Capital','Basket target %','Return %','DD %','Baskets','Win %'],[[r['lineup'],r['capital'],r['basket_target_pct'],n(r['net_return_pct']),n(r['maximum_drawdown_pct']),r['independent_baskets'],n(r['win_rate_pct'])] for r in target_cases]),'','All outcomes are retained, including deteriorations. A better development return alone does not qualify a strategy or justify promoting the new target.']
        lines+=['','The $500 adaptive case worsened from −3.75% to −4.10%; the flagship basket worsened from −3.97% to −5.09%. The target-only change is rejected as a lineup improvement and is not promoted to a default. Trend improved on just one decision, which is insufficient evidence.']
    cadence=[]
    for ms in (5000,200):
        p=ROOT/f'.tmp/turbo-cadence-{ms}.json'
        if p.exists():
            d=load(p);cadence.append(dict(cadence_ms=ms,results=d['results'],sessions=d['sessions']))
            (OUT/f'turbo-cadence-{ms}-receipts.json.gz').write_bytes(gzip.compress(p.read_bytes(),mtime=0))
    if len(cadence)==2:
        write(OUT/'turbo-cadence-diagnostic.json',dict(scope='One known October 14 session, Micro only, $500 / 1% / 0.2% target. Execution-cadence diagnostic, not strategy profitability validation.',cases=cadence))
        lines+=['','## Micro cadence diagnostic','','On the identical 14 October $500 session, 5-second decisions returned +0.57% from one basket; 200 ms decisions returned −0.32% from two baskets. Every raw quote checks broker stops in both. Faster decisions changed admissions and management and did not rescue that session. This confirms cadence sensitivity: the broad 5-second screen cannot certify the live 200 ms Micro worker. A single day cannot validate either cadence.']
    lines+=['','## What this evidence supports','','Crypto trend pullback and the six-family research combination are candidates for forward demo comparison; production arbitration parity must be established before quoting combined returns as production performance; the combination improves participation in this November window, with substantial sampled drawdowns. ETH complementary is slower and does not satisfy a scalp offering. DOGE has only two decisions; LTC and the new compression prototype do not justify promotion. Gold Standard momentum/band rules merit demo comparison only where minimum executable volume fits; higher risk increases severe-loss exposure.','','All five Turbo implementations remain available for development/demo qualification. A profitable arm or profitable aggregate does not validate every component. Do not promote losing components, increase risk to repair their entries, or advertise 20% sessions / monthly doubling. Fresh FX entry validation and multiple unseen chronological periods remain outstanding.','','## Exact engineering improvements and remaining qualification','','Implemented: closed-candle structure cache with per-tick developing-event reassessment; original-feature equality tested. Aggregate account and uncertain pending margin now consume the shared margin budget; lot size reduces to executable headroom and never rounds up beyond risk. Negative free margin is normalized only for protective management facts, while new entries still fail sizing. Research variants require the fake replay terminal, preserving production authorization and conservative defaults.','','Functionally tested: 158 targeted Gold Turbo tests, nine Crypto accounting/execution invariant tests; 576 Crypto and 96 Gold Standard account cash audits. Corrected Turbo accounts audit once their full replay completes. No broad repository test suite or live broker session was run.','','Historically evaluated: retained 16-family ledger; fresh November six-family Crypto OHLC screen; October three-family Gold Standard tick screen; corrected Turbo selected-session replay when receipts above exist. Profitability validated / commercially qualified: not established. Demo activation still requires native MT5 compilation, broker demo integration and recovery/partial-fill checks; venue-specific Crypto order handling; confirmed subscriptions, provider secrets and Telegram setup. Survival flags mean positive modeled ending equity, not a probability of survival. Gold broker stop-out schedules are unverified; Crypto liquidation uses the explicitly approximate maintenance scenario. No live or paid activation.','','Reproduce: restore the source archive, prepare Crypto input, bundle/run `crypto_validation_signals.ts`, then run `crypto_personal_screen.py`. Scripts retain exact source hashes and period boundaries. Gold uses the previously preserved October tick archive; no duplicate download. Read `experiment.json`, `data-index.json`, `crypto-source-data.json`, summaries and compressed receipts for all case settings.']
    lines+=['','## Capital and launch decision','','For demo comparison, prioritize the existing Crypto trend-pullback rule, its curated Trend+VWAP research combination and the six-family research router, with production execution/arbitration parity checked first. Keep every strategy independently selectable; do not assign all 21 by default. One favorable November does not justify selecting the highest-return 3% case as a proven best risk profile. The 5% cases are separate high-risk experiments and sometimes underperform 1%.','','At $100, even the favorable 1% / 10× Crypto case loses $56.66 after a full $100 subscription; at $500 it leaves $130.45 in this one favorable screen. That is evidence against a flat $100 execution offer for $100 accounts, not a promise that $500 accounts cover fees consistently. $5,000/$10,000 pricing and return claims have not been separately measured here. Production capital bands and conservative demo limits remain intact.','','Gold Turbo remains demo-only and unqualified for profitability. Preserve the five engines, but spend the next strategy work on entry quality and net payoff using production-cadence execution, rather than increasing lots, promoting a weak combination, expanding the catalogue or loosening Prop protection. Fresh FX market-entry validation, multiple chronological holdouts, broker-native forward execution and customer onboarding/Telegram/payment verification remain separate outstanding work.']
    (OUT/'RESULTS.md').write_text('\n'.join(lines)+'\n')
    print('Reported',len(rows),'existing configurations;',len(turbo),'corrected Turbo accounts')

if __name__=='__main__':main()
